// plan one shot from an arbitrary position toward green (used by shot view + route)
function planShotFrom(course, hole, profile, pos) {
  const hf = featuresForHole(course, hole);
  const classify = classifierFor(hf, course.bounds);
  const green = hole.green;
  const remaining = dist(pos[0], pos[1], green[0], green[1]);
  if (remaining < 12) return null;
  const dx = green[0] - pos[0], dy = green[1] - pos[1]; const L = Math.hypot(dx, dy) || 1;
  const dirx = dx / L, diry = dy / L;
  const sorted = [...profile.clubs].sort((a, b) => a.carry - b.carry);
  const reacher = sorted.find(c => c.carry >= remaining - 5);
  const layups = sorted.filter(c => c.carry < remaining - 5);
  // Club set: the reacher (if green is in range) + a spread of lay-up clubs so the
  // engine can choose to hang back when straight-on is dangerous.
  const set = [];
  if (reacher) set.push({ club: reacher, playCarry: remaining });
  // include up to 3 lay-up options spread across the bag, not just the longest two
  const layPick = layups.length <= 3 ? layups : [layups[layups.length - 1], layups[Math.floor(layups.length * 0.6)], layups[Math.floor(layups.length * 0.3)]];
  for (const c of layPick) set.push({ club: c, playCarry: c.carry });
  if (!set.length) set.push({ club: sorted[sorted.length - 1], playCarry: Math.min(sorted[sorted.length - 1].carry, remaining) });

  // WIDE aim search. The old code only nudged +/-12y off the dead-straight line, so on
  // holes where the safe line is well off the tee->green axis it was forced to aim into
  // trouble. We now sweep a broad lateral fan (up to ~45y each way) at several carries.
  // The strokes-gained scoring (which punishes OB/trees hard) then naturally selects the
  // in-play line — laying back or aiming wide of hazards as a real caddie would.
  const offsets = [-42, -30, -20, -12, -6, 0, 6, 12, 20, 30, 42];
  const cands = [];
  for (const { club, playCarry } of set) {
    for (const shape of SHAPES) {
      for (const offset of offsets) {
        cands.push({ club, shape, offset, carry: Math.round(playCarry),
          ...evalShot(pos[0], pos[1], dirx, diry, playCarry, offset, shape, profile, classify, green, 260) });
      }
    }
  }
  cands.sort((a, b) => a.expected - b.expected);
  return { remaining: Math.round(remaining), ...cands[0] };
}

function planRoute(course, hole, profile) {
  const green = hole.green; let pos = [...hole.tee]; const shots = []; let guard = 0;
  while (guard++ < 7) {
    const s = planShotFrom(course, hole, profile, pos);
    if (!s) break;
    shots.push({ from: [...pos], ...s });
    pos = [s.cx, s.cy];
    if (shots.length >= 5) break;
  }
  return shots;
}

// Build a single shot from `pos` aimed at an explicit user-chosen target point.
// Picks the best club/shape to cover that distance, lands the dispersion AT the target.
function planShotToTarget(course, hole, profile, pos, target) {
  const classify = classifierFor(featuresForHole(course, hole), course.bounds);
  const reqDist = dist(pos[0], pos[1], target[0], target[1]);
  const dx = target[0] - pos[0], dy = target[1] - pos[1]; const L = Math.hypot(dx, dy) || 1;
  const dirx = dx / L, diry = dy / L;
  const sorted = [...profile.clubs].sort((a, b) => a.carry - b.carry);
  // choose the club whose carry is closest to the required distance
  let club = sorted[sorted.length - 1];
  for (const c of sorted) { if (c.carry >= reqDist - 8) { club = c; break; } }
  // sample dispersion landing exactly on the target (carry = required distance)
  let best = null;
  for (const shape of SHAPES) for (const offset of [-10, 0, 10]) {
    const r = evalShot(pos[0], pos[1], dirx, diry, reqDist, offset, shape, profile, classify, hole.green);
    if (!best || r.expected < best.expected) best = { club, shape, offset, carry: Math.round(reqDist), ...r };
  }
  // force the landing centre to the user's target so the node sits where they dragged it
  best.cx = target[0]; best.cy = target[1];
  best.remaining = Math.round(dist(target[0], target[1], hole.green[0], hole.green[1]));
  best.userPlaced = true;
  return { from: [...pos], ...best };
}

// Route that honours a user-dragged landing spot for one shot, re-planning the rest.
function planRouteWithOverride(course, hole, profile, overrideIndex, overridePos) {
  if (overrideIndex == null || !overridePos) return planRoute(course, hole, profile);
  const base = planRoute(course, hole, profile);
  const shots = [];
  let pos = [...hole.tee];
  for (let i = 0; i <= overrideIndex && i < 6; i++) {
    if (i === overrideIndex) {
      shots.push(planShotToTarget(course, hole, profile, pos, overridePos));
      pos = [...overridePos];
    } else if (base[i]) {
      shots.push({ ...base[i], from: [...pos] });
      pos = [base[i].cx, base[i].cy];
    }
  }
  // re-plan remaining shots from the overridden position
  let guard = 0;
  while (guard++ < 6 && dist(pos[0], pos[1], hole.green[0], hole.green[1]) >= 12) {
    const s = planShotFrom(course, hole, profile, pos);
    if (!s) break;
    shots.push({ from: [...pos], ...s });
    pos = [s.cx, s.cy];
    if (shots.length >= 6) break;
  }
  return shots;
}

// Predicted tee-shot landing scatter from the model (used until real shots are tracked).
function predictTeePattern(course, hole, profile, n = 60) {
  const first = planShotFrom(course, hole, profile, hole.tee);
  if (!first) return { points: [], center: hole.tee };
  const classify = classifierFor(featuresForHole(course, hole), course.bounds);
  const dx = hole.green[0] - hole.tee[0], dy = hole.green[1] - hole.tee[1];
  const L = Math.hypot(dx, dy) || 1; const dirx = dx / L, diry = dy / L;
  const px = -diry, py = dirx;
  const cx = hole.tee[0] + dirx * first.carry + px * (first.offset + first.shape.bias);
  const cy = hole.tee[1] + diry * first.carry + py * (first.offset + first.shape.bias);
  const { lateralSD, downSD } = dispersionForProfile(profile, first.carry);
  const points = [];
  for (let i = 0; i < n; i++) {
    const lat = randn() * lateralSD, dn = randn() * downSD;
    const x = cx + px * lat + dirx * dn, y = cy + py * lat + diry * dn;
    points.push({ x, y, lie: classify(x, y) });
  }
  return { points, center: [cx, cy], lateralSD, downSD };
}

// Actual tracked tee shots for a hole: the FIRST logged shot of each round-session.
// We store shots flat per hole; treat each logged shot whose index===0 within a session as a tee shot.
// Simpler model here: the first shot in the log array is the tee shot of the current session,
// and historical tee shots are kept in shotLog under `${key}:tees`.
function actualTeeShots(shotLog, course, hole) {
  const key = `${course.id}:${hole.ref}:tees`;
  return shotLog[key] || [];
}

// Parse the LLM's JSON plan defensively.
function parsePlan(text) {
  let t = (text || "").trim().replace(/^```json\s*/i, "").replace(/```$/g, "").trim();
  const start = t.indexOf("{"), end = t.lastIndexOf("}");
  if (start === -1 || end === -1) return null;
  try { return JSON.parse(t.slice(start, end + 1)); } catch { return null; }
}



