// ---- lat/lng helpers for satellite tiles ----
const M_PER_DEG = 111320, YD_PER_M = 1.09361;
function yardToLatLng(course, x, y) {
  const c = course.center;
  const lat = c.lat + (y / YD_PER_M) / M_PER_DEG;
  const lon = c.lon + (x / YD_PER_M) / (M_PER_DEG * Math.cos(c.lat * Math.PI / 180));
  return { lat, lon };
}
function latLngToYard(course, lat, lon) {
  const c = course.center;
  const y = (lat - c.lat) * M_PER_DEG * YD_PER_M;
  const x = (lon - c.lon) * M_PER_DEG * Math.cos(c.lat * Math.PI / 180) * YD_PER_M;
  return [x, y];
}
// Web Mercator tile helpers (Esri World Imagery, no key required)
function lon2tileX(lon, z) { return Math.floor(((lon + 180) / 360) * Math.pow(2, z)); }
function lat2tileY(lat, z) { const r = lat * Math.PI / 180; return Math.floor((1 - Math.log(Math.tan(r) + 1 / Math.cos(r)) / Math.PI) / 2 * Math.pow(2, z)); }
function tileX2lon(x, z) { return x / Math.pow(2, z) * 360 - 180; }
function tileY2lat(y, z) { const n = Math.PI - 2 * Math.PI * y / Math.pow(2, z); return 180 / Math.PI * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n))); }
function esriTileUrl(z, x, y) { return `https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/${z}/${y}/${x}`; }

// ============================================================================
// OSM COURSE DISCOVERY & AUTO-DOWNLOAD
// Detects nearby golf courses via the Overpass API, then downloads and parses a
// chosen course's hole geometry into the same shape as the bundled COURSES.
// Overpass is blocked in the artifact sandbox, so every network path falls back
// to bundled/cached data and surfaces an honest status to the UI.
// ============================================================================
const OVERPASS_ENDPOINTS = [
  "https://overpass-api.de/api/interpreter",
  "https://overpass.kumi.systems/api/interpreter",
];
// project a lat/lon to local yards around an explicit [lat,lon] origin
function projectToYards(originLat, originLon, lat, lon) {
  const y = (lat - originLat) * M_PER_DEG * YD_PER_M;
  const x = (lon - originLon) * M_PER_DEG * Math.cos(originLat * Math.PI / 180) * YD_PER_M;
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}
function haversideYd(lat1, lon1, lat2, lon2) {
  const R = 6371000, toR = Math.PI / 180;
  const dLat = (lat2 - lat1) * toR, dLon = (lon2 - lon1) * toR;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * toR) * Math.cos(lat2 * toR) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a)) * YD_PER_M;
}
async function overpassQuery(ql) {
  let lastErr;
  for (const url of OVERPASS_ENDPOINTS) {
    try {
      const res = await fetch(url, { method: "POST", body: "data=" + encodeURIComponent(ql), headers: { "Content-Type": "application/x-www-form-urlencoded" } });
      if (!res.ok) { lastErr = new Error("Overpass " + res.status); continue; }
      return await res.json();
    } catch (e) { lastErr = e; }
  }
  throw lastErr || new Error("Overpass unreachable");
}

// Find golf courses within `radiusM` metres of a point. Returns [{osmId,name,lat,lon,distYd}].
async function discoverNearbyCourses(lat, lon, radiusM = 8000) {
  const ql = `[out:json][timeout:25];(way["leisure"="golf_course"](around:${radiusM},${lat},${lon});relation["leisure"="golf_course"](around:${radiusM},${lat},${lon}););out tags center;`;
  const data = await overpassQuery(ql);
  const seen = new Set();
  const courses = [];
  for (const el of data.elements || []) {
    const c = el.center || (el.lat != null ? { lat: el.lat, lon: el.lon } : null);
    if (!c) continue;
    const name = el.tags?.name || "Unnamed course";
    const key = name + "|" + c.lat.toFixed(3);
    if (seen.has(key)) continue; seen.add(key);
    courses.push({ osmId: `${el.type}/${el.id}`, type: el.type, id: el.id, name, lat: c.lat, lon: c.lon, distYd: Math.round(haversideYd(lat, lon, c.lat, c.lon)) });
  }
  return courses.sort((a, b) => a.distYd - b.distYd);
}

// Download + parse a course's geometry into the COURSES shape. `meta` = a discovery result.
async function downloadCourseGeometry(meta) {
  // pull every golf feature within ~1.5km of the course centre
  const r = 1500;
  const ql = `[out:json][timeout:30];(way["golf"](around:${r},${meta.lat},${meta.lon});way["leisure"="golf_course"](around:${r},${meta.lat},${meta.lon}););(._;>;);out body;`;
  const data = await overpassQuery(ql);
  const nodes = {};
  for (const el of data.elements || []) if (el.type === "node") nodes[el.id] = el;
  const ways = (data.elements || []).filter(el => el.type === "way" && el.nodes);
  const toYd = (la, lo) => projectToYards(meta.lat, meta.lon, la, lo);
  const ringOf = (w) => w.nodes.map(id => nodes[id]).filter(Boolean).map(n => toYd(n.lat, n.lon));
  const centroid = (ring) => { const n = ring.length || 1; return [ring.reduce((s, p) => s + p[0], 0) / n, ring.reduce((s, p) => s + p[1], 0) / n]; };

  const holes = [], greens = [], fairways = [], bunkers = [], tees = [];
  for (const w of ways) {
    const g = w.tags?.golf;
    const ring = ringOf(w);
    if (ring.length < 2) continue;
    if (g === "hole") {
      const ref = w.tags.ref || w.tags.name || String(holes.length + 1);
      const par = parseInt(w.tags.par, 10) || null;
      // hole way is the tee->green centreline; ends are tee and green
      holes.push({ ref: String(ref), par: par || 4, tee: ring[0], green: ring[ring.length - 1], path: ring });
    } else if (g === "green") greens.push(ring);
    else if (g === "fairway") fairways.push(ring);
    else if (g === "bunker") bunkers.push(ring);
    else if (g === "tee") tees.push(ring);
  }
  // pair tees/greens to holes if the hole centreline endpoints are imprecise
  // (snap each hole's green end to the nearest green centroid when close)
  for (const h of holes) {
    let best = null, bd = 40;
    for (const gr of greens) { const c = centroid(gr); const d = dist(h.green[0], h.green[1], c[0], c[1]); if (d < bd) { bd = d; best = c; } }
    if (best) h.green = best;
  }
  const coverage = { holes: holes.length, greens: greens.length, fairways: fairways.length, bunkers: bunkers.length };
  const valid = holes.length > 0;
  // build outer bounds from the golf_course way if present, else a box around features
  let bounds = null;
  const courseWay = ways.find(w => w.tags?.leisure === "golf_course");
  if (courseWay) bounds = ringOf(courseWay);
  if (!bounds || bounds.length < 3) {
    const all = [...holes.flatMap(h => [h.tee, h.green]), ...greens.flat(), ...fairways.flat()];
    if (all.length) {
      const xs = all.map(p => p[0]), ys = all.map(p => p[1]);
      const pad = 60, minX = Math.min(...xs) - pad, maxX = Math.max(...xs) + pad, minY = Math.min(...ys) - pad, maxY = Math.max(...ys) + pad;
      bounds = [[minX, minY], [maxX, minY], [maxX, maxY], [minX, maxY]];
    } else bounds = [[-300, -300], [300, -300], [300, 300], [-300, 300]];
  }
  holes.sort((a, b) => (parseInt(a.ref, 10) || 99) - (parseInt(b.ref, 10) || 99));
  return {
    course: { id: meta.osmId.replace("/", "_"), name: meta.name, center: { lat: meta.lat, lon: meta.lon }, bounds, holes, greens, fairways, bunkers, video: null, source: "osm" },
    coverage, valid,
  };
}

// Bundled fallback list so discovery + download demo without a network (sandbox).
// These reuse the courses already baked into COURSES, presented as "nearby".
function cachedNearbyCourses() {
  return Object.values(COURSES).map(c => ({
    osmId: c.id, type: "cached", id: c.id, name: c.name, lat: c.center.lat, lon: c.center.lon,
    distYd: null, cached: true,
  }));
}

// Compute Esri tiles covering a hole. Tiles are placed in a NON-rotated linear screen space
// (using the same scale `s` and tee anchor as the projection), then the whole tile group is
// rotated by the hole angle so the imagery aligns with the rotated vector geometry on top.
function computeSatTiles(course, hole, hf, proj, VIEW_W, VIEW_H, PAD) {
  const yardPts = [hole.tee, hole.green, ...hf.greens.flat(), ...hf.fairways.flat(), ...hf.bunkers.flat()];
  const lls = yardPts.map(p => yardToLatLng(course, p[0], p[1]));
  let minLat = Math.min(...lls.map(l => l.lat)), maxLat = Math.max(...lls.map(l => l.lat));
  let minLon = Math.min(...lls.map(l => l.lon)), maxLon = Math.max(...lls.map(l => l.lon));
  const padLat = (maxLat - minLat) * 0.7 + 0.001, padLon = (maxLon - minLon) * 0.7 + 0.001;
  minLat -= padLat; maxLat += padLat; minLon -= padLon; maxLon += padLon;
  const z = 17;
  const xT0 = lon2tileX(minLon, z), xT1 = lon2tileX(maxLon, z);
  const yT0 = lat2tileY(maxLat, z), yT1 = lat2tileY(minLat, z);
  // anchor: project the tee through the rotated projection to get its screen point; we rotate
  // the tile group about THAT point, and lay tiles relative to it in unrotated yard-scaled space.
  const teeSX = proj.X(hole.tee[0], hole.tee[1]), teeSY = proj.Y(hole.tee[0], hole.tee[1]);
  const tiles = [];
  for (let tx = xT0; tx <= xT1 && tiles.length < 80; tx++) {
    for (let ty = yT0; ty <= yT1 && tiles.length < 80; ty++) {
      const wLon = tileX2lon(tx, z), eLon = tileX2lon(tx + 1, z);
      const nLat = tileY2lat(ty, z), sLat = tileY2lat(ty + 1, z);
      const nw = latLngToYard(course, nLat, wLon), se = latLngToYard(course, sLat, eLon);
      // unrotated offset from tee in yards -> screen px (scale s, +y downward)
      const x = teeSX + (nw[0] - hole.tee[0]) * proj.s;
      const y = teeSY - (nw[1] - hole.tee[1]) * proj.s;
      const w = (se[0] - nw[0]) * proj.s;
      const h = (nw[1] - se[1]) * proj.s;
      tiles.push({ url: esriTileUrl(z, tx, ty), x, y, w: Math.abs(w), h: Math.abs(h), key: `${z}/${tx}/${ty}` });
    }
  }
  return { tiles, anchor: [teeSX, teeSY] };
}



